<script setup lang="ts">
import { onMounted, reactive, ref } from "vue";
import { Building2, LoaderCircle, Pencil, Plus, Trash2, X } from "lucide-vue-next";
import ConfirmModal from "@/components/operations/ConfirmModal.vue";
import DataPanel from "@/components/operations/DataPanel.vue";
import OpsModal from "@/components/operations/OpsModal.vue";
import StatusBadge from "@/components/operations/StatusBadge.vue";
import { operationsRepository } from "@/data/repositories/operationsRepository";
import type { UiInstituteRecord } from "@/data/models/operations";

const loading = ref(true); const saving = ref(false); const deleting = ref(false); const showForm = ref(false); const error = ref("");
const institutes = ref<UiInstituteRecord[]>([]); const editingId = ref<number | null>(null); const deleteTarget = ref<UiInstituteRecord | null>(null);
const defaults = { name: "", slug: "", code: "", status: "active", billing_email: "", city: "", country_code: "GB", timezone: "Europe/London", settings: {} };
const form = reactive({ ...defaults });
async function load() { loading.value = true; error.value = ""; try { institutes.value = (await operationsRepository.institutes({ per_page: 100 })).items; } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to load institutes."; } finally { loading.value = false; } }
function fromName() { if (!form.slug) form.slug = form.name.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, ""); if (!form.code) form.code = form.name.replace(/[^a-z0-9]/gi, "").slice(0, 8).toUpperCase(); }
function openCreate() { editingId.value = null; Object.assign(form, defaults); showForm.value = true; }
function openEdit(item: UiInstituteRecord) { editingId.value = item.id; Object.assign(form, { name: item.name, slug: item.slug, code: item.code, status: item.status, billing_email: item.billingEmail, city: item.city, country_code: item.countryCode, timezone: item.timezone, settings: item.settings }); showForm.value = true; }
async function saveInstitute() { saving.value = true; error.value = ""; try { if (editingId.value) await operationsRepository.update("institutes", editingId.value, form); else await operationsRepository.create("institutes", form); showForm.value = false; await load(); } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to save institute."; } finally { saving.value = false; } }
async function confirmRemove() { if (!deleteTarget.value) return; deleting.value = true; try { await operationsRepository.remove("institutes", deleteTarget.value.id); deleteTarget.value = null; await load(); } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to delete institute."; } finally { deleting.value = false; } }
onMounted(load);
</script>

<template><div class="space-y-5"><div class="flex flex-wrap items-end justify-between gap-3"><div><p class="text-[12px] font-semibold uppercase tracking-[0.12em] text-mint">Organisation network</p><h2 class="mt-1 text-[26px] font-bold tracking-[-0.035em]">Institutes</h2><p class="mt-1 text-[13px] text-ink3">Create and oversee institute tenants and billing identities.</p></div><button class="ops-button-primary flex items-center gap-2 transition hover:-translate-y-0.5 hover:shadow-md" @click="openCreate"><Plus :size="15" /> New institute</button></div><p v-if="error" class="rounded-xl bg-pink-light px-4 py-3 text-[13px] text-pink">{{ error }}</p><DataPanel title="Institute directory" :description="`${institutes.length} organisations`" :loading="loading" :empty="!institutes.length"><div class="grid gap-4 p-5 md:grid-cols-2 xl:grid-cols-3"><article v-for="item in institutes" :key="item.id" class="group rounded-2xl border border-border p-4 transition duration-200 hover:-translate-y-0.5 hover:border-blue-mid hover:shadow-md"><div class="flex items-start justify-between"><div class="grid h-10 w-10 place-items-center rounded-xl bg-mint-light text-mint transition group-hover:scale-105"><Building2 :size="19" /></div><StatusBadge :value="item.status" /></div><h3 class="mt-4 text-[15px] font-bold">{{ item.name }}</h3><p class="mt-0.5 text-[11px] text-ink3">{{ item.code }} · {{ item.slug }}</p><dl class="mt-4 grid grid-cols-2 gap-3 text-[11px]"><div><dt class="text-ink4">Billing</dt><dd class="mt-0.5 truncate text-ink2">{{ item.billingEmail || 'Not set' }}</dd></div><div><dt class="text-ink4">Location</dt><dd class="mt-0.5 text-ink2">{{ [item.city, item.countryCode].filter(Boolean).join(', ') || 'Not set' }}</dd></div></dl><div class="mt-4 flex items-center justify-end gap-1 border-t border-border pt-3"><RouterLink :to="`/institute/${item.id}`" class="mr-auto text-[11px] font-semibold text-blue">Open workspace</RouterLink><button class="ops-icon-button" title="Edit institute" @click="openEdit(item)"><Pencil :size="14" /></button><button class="ops-icon-button hover:bg-pink-light hover:text-pink" title="Delete institute" @click="deleteTarget = item"><Trash2 :size="14" /></button></div></article></div></DataPanel>
  <OpsModal :open="showForm" max-width="max-w-xl" :close-on-backdrop="!saving" @close="showForm = false"><form class="rounded-2xl border border-border bg-bg-card p-5 shadow-2xl" @submit.prevent="saveInstitute"><div class="mb-5 flex justify-between"><div><h3 class="text-[17px] font-bold">{{ editingId ? 'Edit institute' : 'Create institute' }}</h3><p class="mt-1 text-[12px] text-ink3">{{ editingId ? 'Update tenant identity and operational status.' : 'Members and students can be added after creation.' }}</p></div><button type="button" :disabled="saving" @click="showForm = false"><X :size="18" /></button></div><div class="grid gap-3 sm:grid-cols-2"><label class="text-[11px] font-semibold">Name<input v-model="form.name" required class="ops-input" @blur="fromName" /></label><label class="text-[11px] font-semibold">Billing email<input v-model="form.billing_email" type="email" class="ops-input" /></label><label class="text-[11px] font-semibold">Slug<input v-model="form.slug" required class="ops-input" /></label><label class="text-[11px] font-semibold">Code<input v-model="form.code" required class="ops-input" /></label><label class="text-[11px] font-semibold">City<input v-model="form.city" class="ops-input" /></label><label class="text-[11px] font-semibold">Country code<input v-model="form.country_code" maxlength="2" class="ops-input uppercase" /></label><label class="text-[11px] font-semibold">Timezone<input v-model="form.timezone" class="ops-input" /></label><label class="text-[11px] font-semibold">Status<select v-model="form.status" class="ops-input"><option value="pending">Pending</option><option value="active">Active</option><option value="suspended">Suspended</option><option value="closed">Closed</option></select></label></div><div class="mt-5 flex justify-end gap-2"><button type="button" :disabled="saving" class="ops-button-secondary" @click="showForm = false">Cancel</button><button class="ops-button-primary inline-flex min-w-32 items-center justify-center gap-2" :disabled="saving"><LoaderCircle v-if="saving" :size="14" class="animate-spin" />{{ saving ? 'Saving…' : editingId ? 'Update institute' : 'Create institute' }}</button></div></form></OpsModal>
  <ConfirmModal :open="Boolean(deleteTarget)" title="Delete institute?" :message="`This will remove ${deleteTarget?.name || 'this institute'} and may affect related access. This action cannot be undone.`" confirm-label="Delete institute" :busy="deleting" @close="deleteTarget = null" @confirm="confirmRemove" />
</div></template>
